CREATE INDEX IF NOT EXISTS "ix_tasks_assigned_to" ON "tasks" ("assigned_to");
CREATE INDEX IF NOT EXISTS "ix_tasks_assigned_to_status" ON "tasks" ("assigned_to", "status");

CREATE TABLE IF NOT EXISTS "form_definitions" (
