  "sort_order" SMALLINT NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("name")
);

CREATE TABLE IF NOT EXISTS "saas_subscriptions" (
  "id" CHAR(26) NOT NULL,
