CREATE INDEX IF NOT EXISTS "ix_saas_subscriptions_reseller_id" ON "saas_subscriptions" ("reseller_id");

CREATE TABLE IF NOT EXISTS "saas_invoices" (
  "id" CHAR(26) NOT NULL,
