  "period_start" DATE NOT NULL,
  "period_end" DATE NOT NULL,
  "amount" NUMERIC(14,2) NOT NULL,
  "tax" NUMERIC(14,2) NOT NULL DEFAULT 0,
  "total" NUMERIC(14,2) NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'issued',
  "due_date" DATE NOT NULL,
  "paid_at" TIMESTAMP(3),
  "payment_ref" VARCHAR(120),
  "pdf_file_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("invoice_no"),
  CHECK ("status" IN ('draft', 'issued', 'paid', 'overdue', 'void'))
);
CREATE INDEX IF NOT EXISTS "ix_saas_invoices_school_id" ON "saas_invoices" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_saas_invoices_subscription_id" ON "saas_invoices" ("subscription_id");
CREATE INDEX IF NOT EXISTS "ix_saas_invoices_pdf_file_id" ON "saas_invoices" ("pdf_file_id");

