  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "person_name" VARCHAR(160) NOT NULL,
  "relation" VARCHAR(60),
  "phone" VARCHAR(20),
  "photo_file_id" CHAR(26),
  "id_proof" VARCHAR(60),
  "valid_from" DATE,
  "valid_to" DATE,
  "is_one_time" BOOLEAN NOT NULL DEFAULT FALSE,
  "approved_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_pickup_authorisations_school_id" ON "pickup_authorisations" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_pickup_authorisations_student_id" ON "pickup_authorisations" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_pickup_authorisations_photo_file_id" ON "pickup_authorisations" ("photo_file_id");
CREATE INDEX IF NOT EXISTS "ix_pickup_authorisations_approved_by" ON "pickup_authorisations" ("approved_by");

CREATE TABLE IF NOT EXISTS "student_documents" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "doc_type" VARCHAR(60) NOT NULL,
  "file_id" CHAR(26) NOT NULL,
  "verified_by" CHAR(26),
  "verified_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_student_documents_school_id" ON "student_documents" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_student_documents_student_id" ON "student_documents" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_student_documents_file_id" ON "student_documents" ("file_id");
CREATE INDEX IF NOT EXISTS "ix_student_documents_verified_by" ON "student_documents" ("verified_by");

CREATE TABLE IF NOT EXISTS "student_status_history" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "from_status" VARCHAR(20),
  "to_status" VARCHAR(20) NOT NULL,
