);
CREATE INDEX IF NOT EXISTS "ix_student_status_history_school_id" ON "student_status_history" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_student_status_history_student_id" ON "student_status_history" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_student_status_history_changed_by" ON "student_status_history" ("changed_by");


-- ============ Curriculum & timetable ============
CREATE TABLE IF NOT EXISTS "section_subject_teachers" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "section_id" CHAR(26) NOT NULL,
  "class_subject_id" CHAR(26) NOT NULL,
  "teacher_id" CHAR(26) NOT NULL,
  "is_primary" BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY ("id"),
  UNIQUE ("section_id", "class_subject_id", "teacher_id")
);
CREATE INDEX IF NOT EXISTS "ix_section_subject_teachers_school_id" ON "section_subject_teachers" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_section_subject_teachers_section_id" ON "section_subject_teachers" ("section_id");
CREATE INDEX IF NOT EXISTS "ix_section_subject_teachers_class_subject_id" ON "section_subject_teachers" ("class_subject_id");
CREATE INDEX IF NOT EXISTS "ix_section_subject_teachers_teacher_id" ON "section_subject_teachers" ("teacher_id");

CREATE TABLE IF NOT EXISTS "timetable_versions" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "academic_year_id" CHAR(26) NOT NULL,
  "name" VARCHAR(80) NOT NULL,
  "effective_from" DATE NOT NULL,
  "effective_to" DATE,
  "status" VARCHAR(40) NOT NULL DEFAULT 'draft',
  "generated_by" VARCHAR(40) NOT NULL DEFAULT 'manual',
  "constraints" JSONB,
  "score" NUMERIC(6,2),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('draft', 'published', 'archived')),
  CHECK ("generated_by" IN ('manual', 'auto'))
);
CREATE INDEX IF NOT EXISTS "ix_timetable_versions_school_id" ON "timetable_versions" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_versions_academic_year_id" ON "timetable_versions" ("academic_year_id");

CREATE TABLE IF NOT EXISTS "timetable_slots" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "version_id" CHAR(26) NOT NULL,
  "section_id" CHAR(26) NOT NULL,
  "day_of_week" SMALLINT NOT NULL,
  "period_id" CHAR(26) NOT NULL,
  "class_subject_id" CHAR(26),
  "teacher_id" CHAR(26),
  "room_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("version_id", "section_id", "day_of_week", "period_id"),
  UNIQUE ("version_id", "teacher_id", "day_of_week", "period_id"),
  UNIQUE ("version_id", "room_id", "day_of_week", "period_id")
);
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_school_id" ON "timetable_slots" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_version_id" ON "timetable_slots" ("version_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_section_id" ON "timetable_slots" ("section_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_period_id" ON "timetable_slots" ("period_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_class_subject_id" ON "timetable_slots" ("class_subject_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_teacher_id" ON "timetable_slots" ("teacher_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_slots_room_id" ON "timetable_slots" ("room_id");

CREATE TABLE IF NOT EXISTS "timetable_substitutions" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "slot_id" CHAR(26) NOT NULL,
  "on_date" DATE NOT NULL,
  "original_teacher_id" CHAR(26),
  "substitute_teacher_id" CHAR(26),
  "reason" VARCHAR(60),
  "leave_application_id" CHAR(26),
  "status" VARCHAR(40) NOT NULL DEFAULT 'suggested',
  "is_auto_suggested" BOOLEAN NOT NULL DEFAULT FALSE,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("slot_id", "on_date"),
  CHECK ("status" IN ('suggested', 'pending', 'approved', 'rejected', 'cancelled'))
);
CREATE INDEX IF NOT EXISTS "ix_timetable_substitutions_school_id" ON "timetable_substitutions" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_substitutions_slot_id" ON "timetable_substitutions" ("slot_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_substitutions_original_teacher_id" ON "timetable_substitutions" ("original_teacher_id");
CREATE INDEX IF NOT EXISTS "ix_timetable_substitutions_substitute_teacher_id" ON "timetable_substitutions" ("substitute_teacher_id");

CREATE TABLE IF NOT EXISTS "syllabi" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "class_subject_id" CHAR(26) NOT NULL,
  "term_id" CHAR(26),
  "title" VARCHAR(200) NOT NULL,
  "file_id" CHAR(26),
  "created_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_syllabi_school_id" ON "syllabi" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_syllabi_class_subject_id" ON "syllabi" ("class_subject_id");
CREATE INDEX IF NOT EXISTS "ix_syllabi_term_id" ON "syllabi" ("term_id");
CREATE INDEX IF NOT EXISTS "ix_syllabi_file_id" ON "syllabi" ("file_id");
CREATE INDEX IF NOT EXISTS "ix_syllabi_created_by" ON "syllabi" ("created_by");

CREATE TABLE IF NOT EXISTS "syllabus_units" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "syllabus_id" CHAR(26) NOT NULL,
  "title" VARCHAR(200) NOT NULL,
  "sequence" SMALLINT NOT NULL,
  "planned_periods" SMALLINT NOT NULL DEFAULT 1,
  "planned_end_date" DATE,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("syllabus_id", "sequence")
);
CREATE INDEX IF NOT EXISTS "ix_syllabus_units_school_id" ON "syllabus_units" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_syllabus_units_syllabus_id" ON "syllabus_units" ("syllabus_id");

CREATE TABLE IF NOT EXISTS "learning_outcomes" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "class_subject_id" CHAR(26) NOT NULL,
  "unit_id" CHAR(26),
  "code" VARCHAR(30) NOT NULL,
  "statement" TEXT NOT NULL,
  "statement_bn" TEXT,
  "bloom_level" VARCHAR(40),
  "weight" NUMERIC(4,2) NOT NULL DEFAULT 1,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("class_subject_id", "code"),
  CHECK ("bloom_level" IN ('remember', 'understand', 'apply', 'analyse', 'evaluate', 'create'))
);
CREATE INDEX IF NOT EXISTS "ix_learning_outcomes_school_id" ON "learning_outcomes" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_learning_outcomes_class_subject_id" ON "learning_outcomes" ("class_subject_id");
CREATE INDEX IF NOT EXISTS "ix_learning_outcomes_unit_id" ON "learning_outcomes" ("unit_id");

CREATE TABLE IF NOT EXISTS "lesson_plans" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "teacher_id" CHAR(26) NOT NULL,
  "section_id" CHAR(26) NOT NULL,
  "class_subject_id" CHAR(26) NOT NULL,
  "unit_id" CHAR(26),
  "plan_date" DATE NOT NULL,
  "topic" VARCHAR(200) NOT NULL,
  "objectives" TEXT,
  "activities" TEXT,
  "outcomes" JSONB,
  "resources" JSONB,
  "homework" TEXT,
  "status" VARCHAR(40) NOT NULL DEFAULT 'planned',
  "taught_at" TIMESTAMP(3),
  "reviewed_by" CHAR(26),
  "review_note" TEXT,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('planned', 'taught', 'skipped'))
);
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_school_id" ON "lesson_plans" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_teacher_id" ON "lesson_plans" ("teacher_id");
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_section_id" ON "lesson_plans" ("section_id");
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_class_subject_id" ON "lesson_plans" ("class_subject_id");
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_unit_id" ON "lesson_plans" ("unit_id");
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_reviewed_by" ON "lesson_plans" ("reviewed_by");
CREATE INDEX IF NOT EXISTS "ix_lesson_plans_teacher_id_plan_date" ON "lesson_plans" ("teacher_id", "plan_date");

CREATE TABLE IF NOT EXISTS "syllabus_progress" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "syllabus_id" CHAR(26) NOT NULL,
  "section_id" CHAR(26) NOT NULL,
  "total_units" SMALLINT NOT NULL DEFAULT 0,
  "taught_units" SMALLINT NOT NULL DEFAULT 0,
  "pct" NUMERIC(5,2) NOT NULL DEFAULT 0,
  "refreshed_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("syllabus_id", "section_id")
);
CREATE INDEX IF NOT EXISTS "ix_syllabus_progress_school_id" ON "syllabus_progress" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_syllabus_progress_syllabus_id" ON "syllabus_progress" ("syllabus_id");
CREATE INDEX IF NOT EXISTS "ix_syllabus_progress_section_id" ON "syllabus_progress" ("section_id");


-- ============ Admissions & enquiry CRM ============
CREATE TABLE IF NOT EXISTS "admission_campaigns" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "academic_year_id" CHAR(26) NOT NULL,
  "name" VARCHAR(120) NOT NULL,
  "opens_at" TIMESTAMP(3) NOT NULL,
  "closes_at" TIMESTAMP(3) NOT NULL,
  "form_fee" NUMERIC(14,2) NOT NULL DEFAULT 0,
  "admission_fee_head_id" CHAR(26),
  "selection_mode" VARCHAR(40) NOT NULL DEFAULT 'test',
  "requires_test" BOOLEAN NOT NULL DEFAULT TRUE,
  "auto_merit_list" BOOLEAN NOT NULL DEFAULT TRUE,
  "auto_offer" BOOLEAN NOT NULL DEFAULT TRUE,
  "offer_validity_days" SMALLINT NOT NULL DEFAULT 7,
  "sibling_priority" BOOLEAN NOT NULL DEFAULT TRUE,
  "status" VARCHAR(40) NOT NULL DEFAULT 'draft',
  "public_form_slug" VARCHAR(80),
  "form_schema" JSONB,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("public_form_slug"),
  CHECK ("selection_mode" IN ('test', 'lottery', 'first_come', 'interview', 'mixed')),
  CHECK ("status" IN ('draft', 'open', 'closed', 'archived'))
);
CREATE INDEX IF NOT EXISTS "ix_admission_campaigns_school_id" ON "admission_campaigns" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_admission_campaigns_academic_year_id" ON "admission_campaigns" ("academic_year_id");

CREATE TABLE IF NOT EXISTS "admission_campaign_classes" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "campaign_id" CHAR(26) NOT NULL,
  "class_id" CHAR(26) NOT NULL,
  "seats" SMALLINT NOT NULL,
  "min_age_years" NUMERIC(4,1),
  "max_age_years" NUMERIC(4,1),
  "test_id" CHAR(26),
  PRIMARY KEY ("id"),
  UNIQUE ("campaign_id", "class_id")
);
CREATE INDEX IF NOT EXISTS "ix_admission_campaign_classes_school_id" ON "admission_campaign_classes" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_admission_campaign_classes_campaign_id" ON "admission_campaign_classes" ("campaign_id");
CREATE INDEX IF NOT EXISTS "ix_admission_campaign_classes_class_id" ON "admission_campaign_classes" ("class_id");

CREATE TABLE IF NOT EXISTS "admission_enquiries" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "campaign_id" CHAR(26),
  "student_name" VARCHAR(160) NOT NULL,
  "guardian_name" VARCHAR(160) NOT NULL,
  "phone" VARCHAR(20) NOT NULL,
  "email" VARCHAR(160),
  "class_id" CHAR(26),
  "source" VARCHAR(40) NOT NULL DEFAULT 'other',
  "assigned_to" CHAR(26),
  "status" VARCHAR(40) NOT NULL DEFAULT 'new',
  "lost_reason" VARCHAR(120),
  "next_follow_up_at" TIMESTAMP(3),
  "notes" TEXT,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("source" IN ('walk_in', 'website', 'facebook', 'referral', 'call', 'whatsapp', 'event', 'other')),
  CHECK ("status" IN ('new', 'contacted', 'visited', 'converted', 'lost'))
);
CREATE INDEX IF NOT EXISTS "ix_admission_enquiries_school_id" ON "admission_enquiries" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_admission_enquiries_campaign_id" ON "admission_enquiries" ("campaign_id");
CREATE INDEX IF NOT EXISTS "ix_admission_enquiries_class_id" ON "admission_enquiries" ("class_id");
CREATE INDEX IF NOT EXISTS "ix_admission_enquiries_assigned_to" ON "admission_enquiries" ("assigned_to");
CREATE INDEX IF NOT EXISTS "ix_admission_enquiries_next_follow_up_at" ON "admission_enquiries" ("next_follow_up_at");

CREATE TABLE IF NOT EXISTS "enquiry_followups" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "enquiry_id" CHAR(26) NOT NULL,
  "note" TEXT NOT NULL,
  "channel" VARCHAR(40),
  "by_user_id" CHAR(26),
  "next_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("channel" IN ('call', 'visit', 'sms', 'email', 'whatsapp'))
);
CREATE INDEX IF NOT EXISTS "ix_enquiry_followups_school_id" ON "enquiry_followups" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_enquiry_followups_enquiry_id" ON "enquiry_followups" ("enquiry_id");
CREATE INDEX IF NOT EXISTS "ix_enquiry_followups_by_user_id" ON "enquiry_followups" ("by_user_id");

CREATE TABLE IF NOT EXISTS "admission_applications" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "campaign_id" CHAR(26) NOT NULL,
  "enquiry_id" CHAR(26),
  "application_no" VARCHAR(30) NOT NULL,
  "class_id" CHAR(26) NOT NULL,
  "shift_id" CHAR(26),
  "first_name" VARCHAR(80) NOT NULL,
  "last_name" VARCHAR(80),
  "gender" VARCHAR(40) NOT NULL,
  "date_of_birth" DATE NOT NULL,
  "photo_file_id" CHAR(26),
  "guardian_name" VARCHAR(160) NOT NULL,
  "guardian_phone" VARCHAR(20) NOT NULL,
  "guardian_email" VARCHAR(160),
  "guardian_relation" VARCHAR(30),
  "address" JSONB,
  "previous_school" JSONB,
  "extra_fields" JSONB,
  "sibling_student_id" CHAR(26),
  "status" VARCHAR(40) NOT NULL DEFAULT 'draft',
  "form_fee_invoice_id" CHAR(26),
  "test_score" NUMERIC(6,2),
  "merit_rank" INTEGER,
  "lottery_no" VARCHAR(20),
  "waitlist_position" INTEGER,
  "student_id" CHAR(26),
  "submitted_at" TIMESTAMP(3),
  "decided_at" TIMESTAMP(3),
  "decided_by" CHAR(26),
  "rejection_reason" VARCHAR(255),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "application_no"),
  CHECK ("gender" IN ('male', 'female', 'other')),
  CHECK ("status" IN ('draft', 'submitted', 'screening', 'test_scheduled', 'tested', 'shortlisted', 'waitlisted', 'offered', 'accepted', 'enrolled', 'rejected', 'withdrawn'))
);
CREATE INDEX IF NOT EXISTS "ix_admission_applications_school_id" ON "admission_applications" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_campaign_id" ON "admission_applications" ("campaign_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_enquiry_id" ON "admission_applications" ("enquiry_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_class_id" ON "admission_applications" ("class_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_shift_id" ON "admission_applications" ("shift_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_photo_file_id" ON "admission_applications" ("photo_file_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_sibling_student_id" ON "admission_applications" ("sibling_student_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_student_id" ON "admission_applications" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_decided_by" ON "admission_applications" ("decided_by");
CREATE INDEX IF NOT EXISTS "ix_admission_applications_campaign_id_class_id_status" ON "admission_applications" ("campaign_id", "class_id", "status");

