CREATE TABLE IF NOT EXISTS "student_transport" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "academic_year_id" CHAR(26) NOT NULL,
  "route_id" CHAR(26) NOT NULL,
  "stop_id" CHAR(26) NOT NULL,
  "trip_type" VARCHAR(40) NOT NULL DEFAULT 'both',
  "start_date" DATE NOT NULL,
  "end_date" DATE,
  "monthly_fee" NUMERIC(14,2) NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("student_id", "academic_year_id"),
  CHECK ("trip_type" IN ('pickup', 'drop', 'both')),
  CHECK ("status" IN ('active', 'inactive'))
);
CREATE INDEX IF NOT EXISTS "ix_student_transport_school_id" ON "student_transport" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_student_transport_student_id" ON "student_transport" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_student_transport_academic_year_id" ON "student_transport" ("academic_year_id");
CREATE INDEX IF NOT EXISTS "ix_student_transport_route_id" ON "student_transport" ("route_id");
CREATE INDEX IF NOT EXISTS "ix_student_transport_stop_id" ON "student_transport" ("stop_id");

CREATE TABLE IF NOT EXISTS "vehicle_trips" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "vehicle_id" CHAR(26) NOT NULL,
  "route_id" CHAR(26) NOT NULL,
  "trip_date" DATE NOT NULL,
  "trip_type" VARCHAR(40) NOT NULL,
  "driver_id" CHAR(26),
  "helper_id" CHAR(26),
  "scheduled_start" TIME,
  "started_at" TIMESTAMP(3),
  "ended_at" TIMESTAMP(3),
  "status" VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  "delay_alert_sent_at" TIMESTAMP(3),
  "checklist" JSONB,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("vehicle_id", "trip_date", "trip_type"),
  CHECK ("trip_type" IN ('pickup', 'drop')),
  CHECK ("status" IN ('scheduled', 'running', 'completed', 'cancelled', 'delayed'))
);
CREATE INDEX IF NOT EXISTS "ix_vehicle_trips_school_id" ON "vehicle_trips" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_trips_vehicle_id" ON "vehicle_trips" ("vehicle_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_trips_route_id" ON "vehicle_trips" ("route_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_trips_driver_id" ON "vehicle_trips" ("driver_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_trips_helper_id" ON "vehicle_trips" ("helper_id");

CREATE TABLE IF NOT EXISTS "vehicle_gps_logs" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "vehicle_id" CHAR(26) NOT NULL,
  "trip_id" CHAR(26),
  "latitude" NUMERIC(9,6) NOT NULL,
  "longitude" NUMERIC(9,6) NOT NULL,
  "speed_kmh" NUMERIC(5,1),
  "heading" SMALLINT,
  "recorded_at" TIMESTAMP(3) NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_vehicle_gps_logs_school_id" ON "vehicle_gps_logs" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_gps_logs_vehicle_id" ON "vehicle_gps_logs" ("vehicle_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_gps_logs_trip_id" ON "vehicle_gps_logs" ("trip_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_gps_logs_vehicle_id_recorded_at" ON "vehicle_gps_logs" ("vehicle_id", "recorded_at");

CREATE TABLE IF NOT EXISTS "transport_boardings" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "trip_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "stop_id" CHAR(26),
  "boarded_at" TIMESTAMP(3),
  "alighted_at" TIMESTAMP(3),
  "source" VARCHAR(40) NOT NULL DEFAULT 'rfid',
  "guardian_notified_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("trip_id", "student_id"),
  CHECK ("source" IN ('rfid', 'helper_app', 'manual'))
);
CREATE INDEX IF NOT EXISTS "ix_transport_boardings_school_id" ON "transport_boardings" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_transport_boardings_trip_id" ON "transport_boardings" ("trip_id");
CREATE INDEX IF NOT EXISTS "ix_transport_boardings_student_id" ON "transport_boardings" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_transport_boardings_stop_id" ON "transport_boardings" ("stop_id");

CREATE TABLE IF NOT EXISTS "stop_alerts" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "trip_id" CHAR(26) NOT NULL,
  "stop_id" CHAR(26) NOT NULL,
  "alert_type" VARCHAR(40) NOT NULL,
  "sent_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("trip_id", "stop_id", "alert_type"),
  CHECK ("alert_type" IN ('approaching', 'arrived', 'departed'))
);
CREATE INDEX IF NOT EXISTS "ix_stop_alerts_school_id" ON "stop_alerts" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_stop_alerts_trip_id" ON "stop_alerts" ("trip_id");
CREATE INDEX IF NOT EXISTS "ix_stop_alerts_stop_id" ON "stop_alerts" ("stop_id");

CREATE TABLE IF NOT EXISTS "vehicle_maintenance" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "vehicle_id" CHAR(26) NOT NULL,
  "service_type" VARCHAR(60) NOT NULL,
  "service_date" DATE NOT NULL,
  "odometer_km" INTEGER,
  "cost" NUMERIC(14,2),
  "vendor_id" CHAR(26),
  "expense_id" CHAR(26),
  "next_due_date" DATE,
  "next_due_km" INTEGER,
  "notes" TEXT,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_vehicle_maintenance_school_id" ON "vehicle_maintenance" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_maintenance_vehicle_id" ON "vehicle_maintenance" ("vehicle_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_maintenance_vendor_id" ON "vehicle_maintenance" ("vendor_id");
CREATE INDEX IF NOT EXISTS "ix_vehicle_maintenance_expense_id" ON "vehicle_maintenance" ("expense_id");

CREATE TABLE IF NOT EXISTS "fuel_logs" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "vehicle_id" CHAR(26) NOT NULL,
  "filled_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "litres" NUMERIC(7,2) NOT NULL,
  "cost" NUMERIC(14,2) NOT NULL,
  "odometer_km" INTEGER,
  "expense_id" CHAR(26),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_fuel_logs_school_id" ON "fuel_logs" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_fuel_logs_vehicle_id" ON "fuel_logs" ("vehicle_id");
CREATE INDEX IF NOT EXISTS "ix_fuel_logs_expense_id" ON "fuel_logs" ("expense_id");

CREATE TABLE IF NOT EXISTS "driver_incidents" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "vehicle_id" CHAR(26) NOT NULL,
  "driver_id" CHAR(26),
  "kind" VARCHAR(40) NOT NULL,
  "occurred_at" TIMESTAMP(3) NOT NULL,
  "details" TEXT,
  "severity" VARCHAR(40) NOT NULL DEFAULT 'low',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("kind" IN ('overspeed', 'accident', 'complaint', 'breakdown', 'other')),
  CHECK ("severity" IN ('low', 'medium', 'high'))
);
CREATE INDEX IF NOT EXISTS "ix_driver_incidents_school_id" ON "driver_incidents" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_driver_incidents_vehicle_id" ON "driver_incidents" ("vehicle_id");
CREATE INDEX IF NOT EXISTS "ix_driver_incidents_driver_id" ON "driver_incidents" ("driver_id");


-- ============ Hostel ============
CREATE TABLE IF NOT EXISTS "hostels" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "campus_id" CHAR(26),
  "name" VARCHAR(120) NOT NULL,
  "hostel_type" VARCHAR(40) NOT NULL,
  "warden_id" CHAR(26),
  "address" JSONB,
  "curfew_time" TIME,
  "fee_head_id" CHAR(26),
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "name"),
  CHECK ("hostel_type" IN ('boys', 'girls', 'staff')),
  CHECK ("status" IN ('active', 'inactive'))
);
CREATE INDEX IF NOT EXISTS "ix_hostels_school_id" ON "hostels" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostels_campus_id" ON "hostels" ("campus_id");
CREATE INDEX IF NOT EXISTS "ix_hostels_warden_id" ON "hostels" ("warden_id");
CREATE INDEX IF NOT EXISTS "ix_hostels_fee_head_id" ON "hostels" ("fee_head_id");

CREATE TABLE IF NOT EXISTS "hostel_rooms" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "room_no" VARCHAR(20) NOT NULL,
  "floor" VARCHAR(10),
  "room_type" VARCHAR(40) NOT NULL DEFAULT 'shared',
  "capacity" SMALLINT NOT NULL,
  "monthly_fee" NUMERIC(14,2) NOT NULL DEFAULT 0,
  "amenities" JSONB,
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("hostel_id", "room_no"),
  CHECK ("room_type" IN ('single', 'double', 'shared', 'dorm')),
  CHECK ("status" IN ('active', 'maintenance', 'inactive'))
);
CREATE INDEX IF NOT EXISTS "ix_hostel_rooms_school_id" ON "hostel_rooms" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_rooms_hostel_id" ON "hostel_rooms" ("hostel_id");

CREATE TABLE IF NOT EXISTS "hostel_beds" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "room_id" CHAR(26) NOT NULL,
  "bed_no" VARCHAR(10) NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'vacant',
  PRIMARY KEY ("id"),
  UNIQUE ("room_id", "bed_no"),
  CHECK ("status" IN ('vacant', 'occupied', 'maintenance'))
);
CREATE INDEX IF NOT EXISTS "ix_hostel_beds_school_id" ON "hostel_beds" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_beds_room_id" ON "hostel_beds" ("room_id");

CREATE TABLE IF NOT EXISTS "hostel_allocations" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "bed_id" CHAR(26) NOT NULL,
  "academic_year_id" CHAR(26) NOT NULL,
  "from_date" DATE NOT NULL,
  "to_date" DATE,
  "monthly_fee" NUMERIC(14,2) NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('active', 'ended'))
);
CREATE INDEX IF NOT EXISTS "ix_hostel_allocations_school_id" ON "hostel_allocations" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_allocations_student_id" ON "hostel_allocations" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_allocations_bed_id" ON "hostel_allocations" ("bed_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_allocations_academic_year_id" ON "hostel_allocations" ("academic_year_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_allocations_bed_id_from_date" ON "hostel_allocations" ("bed_id", "from_date");

CREATE TABLE IF NOT EXISTS "hostel_outpasses" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "leave_from" TIMESTAMP(3) NOT NULL,
  "expected_return" TIMESTAMP(3) NOT NULL,
  "actual_out_at" TIMESTAMP(3),
  "actual_return_at" TIMESTAMP(3),
  "reason" VARCHAR(200) NOT NULL,
  "destination" VARCHAR(160),
  "guardian_consent_at" TIMESTAMP(3),
  "status" VARCHAR(40) NOT NULL DEFAULT 'pending',
  "approved_by" CHAR(26),
  "qr_code" VARCHAR(64),
  "late_alert_sent_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('pending', 'approved', 'rejected', 'out', 'returned', 'late'))
);
CREATE INDEX IF NOT EXISTS "ix_hostel_outpasses_school_id" ON "hostel_outpasses" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_outpasses_student_id" ON "hostel_outpasses" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_outpasses_hostel_id" ON "hostel_outpasses" ("hostel_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_outpasses_approved_by" ON "hostel_outpasses" ("approved_by");

CREATE TABLE IF NOT EXISTS "hostel_visitors" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "visitor_name" VARCHAR(160) NOT NULL,
  "relation" VARCHAR(40),
  "phone" VARCHAR(20),
  "id_proof" VARCHAR(60),
  "in_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "out_at" TIMESTAMP(3),
  "approved_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_hostel_visitors_school_id" ON "hostel_visitors" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_visitors_hostel_id" ON "hostel_visitors" ("hostel_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_visitors_student_id" ON "hostel_visitors" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_visitors_approved_by" ON "hostel_visitors" ("approved_by");

CREATE TABLE IF NOT EXISTS "hostel_attendance" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "on_date" DATE NOT NULL,
  "roll_call" VARCHAR(40) NOT NULL DEFAULT 'night',
  "status" VARCHAR(40) NOT NULL,
  "marked_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("student_id", "on_date", "roll_call"),
  CHECK ("roll_call" IN ('morning', 'night')),
  CHECK ("status" IN ('present', 'absent', 'on_outpass', 'sick'))
);
CREATE INDEX IF NOT EXISTS "ix_hostel_attendance_school_id" ON "hostel_attendance" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_attendance_hostel_id" ON "hostel_attendance" ("hostel_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_attendance_student_id" ON "hostel_attendance" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_attendance_marked_by" ON "hostel_attendance" ("marked_by");

CREATE TABLE IF NOT EXISTS "mess_menus" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "day_of_week" SMALLINT NOT NULL,
  "meal" VARCHAR(40) NOT NULL,
  "items" VARCHAR(255) NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("hostel_id", "day_of_week", "meal"),
  CHECK ("meal" IN ('breakfast', 'lunch', 'snack', 'dinner'))
);
CREATE INDEX IF NOT EXISTS "ix_mess_menus_school_id" ON "mess_menus" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_mess_menus_hostel_id" ON "mess_menus" ("hostel_id");

CREATE TABLE IF NOT EXISTS "meal_records" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "on_date" DATE NOT NULL,
  "meal" VARCHAR(40) NOT NULL,
  "taken" BOOLEAN NOT NULL DEFAULT TRUE,
  "cost" NUMERIC(14,2),
  PRIMARY KEY ("id"),
  UNIQUE ("student_id", "on_date", "meal"),
  CHECK ("meal" IN ('breakfast', 'lunch', 'snack', 'dinner'))
);
CREATE INDEX IF NOT EXISTS "ix_meal_records_school_id" ON "meal_records" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_meal_records_hostel_id" ON "meal_records" ("hostel_id");
CREATE INDEX IF NOT EXISTS "ix_meal_records_student_id" ON "meal_records" ("student_id");

CREATE TABLE IF NOT EXISTS "laundry_records" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "dropped_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "items" SMALLINT NOT NULL,
  "returned_at" TIMESTAMP(3),
  "charge" NUMERIC(14,2),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_laundry_records_school_id" ON "laundry_records" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_laundry_records_hostel_id" ON "laundry_records" ("hostel_id");
CREATE INDEX IF NOT EXISTS "ix_laundry_records_student_id" ON "laundry_records" ("student_id");

CREATE TABLE IF NOT EXISTS "hostel_complaints" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "hostel_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26),
  "category" VARCHAR(40) NOT NULL,
  "description" TEXT NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'open',
  "resolved_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("category" IN ('maintenance', 'food', 'safety', 'cleanliness', 'other')),
  CHECK ("status" IN ('open', 'in_progress', 'resolved'))
);
CREATE INDEX IF NOT EXISTS "ix_hostel_complaints_school_id" ON "hostel_complaints" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_complaints_hostel_id" ON "hostel_complaints" ("hostel_id");
CREATE INDEX IF NOT EXISTS "ix_hostel_complaints_student_id" ON "hostel_complaints" ("student_id");


-- ============ Procurement, inventory & assets ============
CREATE TABLE IF NOT EXISTS "inventory_categories" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "name" VARCHAR(80) NOT NULL,
  "is_asset" BOOLEAN NOT NULL DEFAULT FALSE,
  "gl_account_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "name")
);
CREATE INDEX IF NOT EXISTS "ix_inventory_categories_school_id" ON "inventory_categories" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_inventory_categories_gl_account_id" ON "inventory_categories" ("gl_account_id");

CREATE TABLE IF NOT EXISTS "stores" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "name" VARCHAR(80) NOT NULL,
  "campus_id" CHAR(26),
  "keeper_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "name")
);
CREATE INDEX IF NOT EXISTS "ix_stores_school_id" ON "stores" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_stores_campus_id" ON "stores" ("campus_id");
CREATE INDEX IF NOT EXISTS "ix_stores_keeper_id" ON "stores" ("keeper_id");

CREATE TABLE IF NOT EXISTS "inventory_items" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "category_id" CHAR(26) NOT NULL,
  "sku" VARCHAR(40) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "unit" VARCHAR(20) NOT NULL DEFAULT 'pcs',
  "reorder_level" NUMERIC(12,2) NOT NULL DEFAULT 0,
  "reorder_qty" NUMERIC(12,2),
  "preferred_vendor_id" CHAR(26),
  "last_cost" NUMERIC(14,2),
  "barcode" VARCHAR(60),
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "sku"),
  CHECK ("status" IN ('active', 'inactive'))
);
CREATE INDEX IF NOT EXISTS "ix_inventory_items_school_id" ON "inventory_items" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_inventory_items_category_id" ON "inventory_items" ("category_id");
CREATE INDEX IF NOT EXISTS "ix_inventory_items_preferred_vendor_id" ON "inventory_items" ("preferred_vendor_id");

CREATE TABLE IF NOT EXISTS "stock_levels" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "item_id" CHAR(26) NOT NULL,
  "store_id" CHAR(26) NOT NULL,
  "quantity" NUMERIC(12,2) NOT NULL DEFAULT 0,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("item_id", "store_id")
);
CREATE INDEX IF NOT EXISTS "ix_stock_levels_school_id" ON "stock_levels" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_stock_levels_item_id" ON "stock_levels" ("item_id");
CREATE INDEX IF NOT EXISTS "ix_stock_levels_store_id" ON "stock_levels" ("store_id");

CREATE TABLE IF NOT EXISTS "requisitions" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "requested_by" CHAR(26) NOT NULL,
  "department_id" CHAR(26),
  "items" JSONB,
  "justification" TEXT,
  "status" VARCHAR(40) NOT NULL DEFAULT 'pending',
  "approval_request_id" CHAR(26),
  "approved_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("status" IN ('pending', 'approved', 'rejected', 'ordered'))
);
CREATE INDEX IF NOT EXISTS "ix_requisitions_school_id" ON "requisitions" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_requisitions_requested_by" ON "requisitions" ("requested_by");
CREATE INDEX IF NOT EXISTS "ix_requisitions_department_id" ON "requisitions" ("department_id");
CREATE INDEX IF NOT EXISTS "ix_requisitions_approved_by" ON "requisitions" ("approved_by");

CREATE TABLE IF NOT EXISTS "quotations" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "requisition_id" CHAR(26),
  "vendor_id" CHAR(26) NOT NULL,
  "quoted_at" DATE NOT NULL,
  "valid_until" DATE,
  "items" JSONB,
  "total" NUMERIC(14,2) NOT NULL,
  "file_id" CHAR(26),
