CREATE TABLE IF NOT EXISTS "behaviour_categories" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "name" VARCHAR(120) NOT NULL,
  "polarity" VARCHAR(40) NOT NULL,
