  "decided_by" CHAR(26),
  "decided_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("person_type" IN ('student', 'staff', 'alumni')),
  CHECK ("status" IN ('requested', 'blocked', 'approved', 'issued', 'rejected'))
);
CREATE INDEX IF NOT EXISTS "ix_document_requests_school_id" ON "document_requests" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_document_requests_student_id" ON "document_requests" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_document_requests_staff_id" ON "document_requests" ("staff_id");
CREATE INDEX IF NOT EXISTS "ix_document_requests_requested_by" ON "document_requests" ("requested_by");
CREATE INDEX IF NOT EXISTS "ix_document_requests_fee_invoice_id" ON "document_requests" ("fee_invoice_id");
CREATE INDEX IF NOT EXISTS "ix_document_requests_decided_by" ON "document_requests" ("decided_by");

CREATE TABLE IF NOT EXISTS "issued_documents" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "template_id" CHAR(26),
  "request_id" CHAR(26),
  "doc_type" VARCHAR(40) NOT NULL,
  "document_no" VARCHAR(40) NOT NULL,
