CREATE INDEX IF NOT EXISTS "ix_issued_documents_template_id" ON "issued_documents" ("template_id");
CREATE INDEX IF NOT EXISTS "ix_issued_documents_request_id" ON "issued_documents" ("request_id");
CREATE INDEX IF NOT EXISTS "ix_issued_documents_student_id" ON "issued_documents" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_issued_documents_staff_id" ON "issued_documents" ("staff_id");
CREATE INDEX IF NOT EXISTS "ix_issued_documents_file_id" ON "issued_documents" ("file_id");
CREATE INDEX IF NOT EXISTS "ix_issued_documents_signed_by" ON "issued_documents" ("signed_by");
CREATE INDEX IF NOT EXISTS "ix_issued_documents_student_id_doc_type" ON "issued_documents" ("student_id", "doc_type");

CREATE TABLE IF NOT EXISTS "id_cards" (
  "id" CHAR(26) NOT NULL,
