-- ============ Events & ticketing ============
CREATE TABLE IF NOT EXISTS "events" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "calendar_event_id" CHAR(26),
  "title" VARCHAR(200) NOT NULL,
  "description" TEXT,
  "event_type" VARCHAR(40) NOT NULL,
  "starts_at" TIMESTAMP(3) NOT NULL,
  "ends_at" TIMESTAMP(3),
  "venue" VARCHAR(160),
  "room_id" CHAR(26),
  "audience" JSONB,
