  "ticket_price" NUMERIC(14,2),
  "ticket_limit" INTEGER,
  "fee_head_id" CHAR(26),
  "banner_file_id" CHAR(26),
  "organiser_id" CHAR(26),
  "status" VARCHAR(40) NOT NULL DEFAULT 'scheduled',
  "feedback_form_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("event_type" IN ('sports', 'cultural', 'ptm', 'seminar', 'trip', 'ceremony', 'competition', 'workshop', 'other')),
  CHECK ("status" IN ('draft', 'scheduled', 'live', 'completed', 'cancelled'))
);
