CREATE INDEX IF NOT EXISTS "ix_events_fee_head_id" ON "events" ("fee_head_id");
CREATE INDEX IF NOT EXISTS "ix_events_banner_file_id" ON "events" ("banner_file_id");
CREATE INDEX IF NOT EXISTS "ix_events_organiser_id" ON "events" ("organiser_id");
CREATE INDEX IF NOT EXISTS "ix_events_feedback_form_id" ON "events" ("feedback_form_id");

