CREATE INDEX IF NOT EXISTS "ix_event_rsvps_user_id" ON "event_rsvps" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_event_rsvps_student_id" ON "event_rsvps" ("student_id");

