CREATE INDEX IF NOT EXISTS "ix_election_votes_election_id" ON "election_votes" ("election_id");


-- ============ Compliance & government reporting ============
CREATE TABLE IF NOT EXISTS "govt_reports" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "report_type" VARCHAR(40) NOT NULL,
  "period" VARCHAR(20) NOT NULL,
  "data" JSONB,
  "file_id" CHAR(26),
  "submitted_at" TIMESTAMP(3),
  "status" VARCHAR(40) NOT NULL DEFAULT 'draft',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("report_type" IN ('banbeis_census', 'board_registration', 'mpo_salary_sheet', 'stipend_list', 'annual_return', 'custom')),
  CHECK ("status" IN ('draft', 'generated', 'submitted', 'accepted'))
);
CREATE INDEX IF NOT EXISTS "ix_govt_reports_school_id" ON "govt_reports" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_govt_reports_file_id" ON "govt_reports" ("file_id");

CREATE TABLE IF NOT EXISTS "stipend_programs" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "authority" VARCHAR(120),
  "criteria" JSONB,
  "amount" NUMERIC(14,2),
  "frequency" VARCHAR(40),
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("frequency" IN ('monthly', 'quarterly', 'half_yearly', 'yearly')),
  CHECK ("status" IN ('active', 'closed'))
);
CREATE INDEX IF NOT EXISTS "ix_stipend_programs_school_id" ON "stipend_programs" ("school_id");

CREATE TABLE IF NOT EXISTS "stipend_enrollments" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "program_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "enrolled_on" DATE NOT NULL,
  "bank_or_mfs" JSONB,
  "disbursements" JSONB,
  "status" VARCHAR(40) NOT NULL DEFAULT 'active',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("program_id", "student_id"),
  CHECK ("status" IN ('active', 'suspended', 'ended'))
);
CREATE INDEX IF NOT EXISTS "ix_stipend_enrollments_school_id" ON "stipend_enrollments" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_stipend_enrollments_program_id" ON "stipend_enrollments" ("program_id");
CREATE INDEX IF NOT EXISTS "ix_stipend_enrollments_student_id" ON "stipend_enrollments" ("student_id");

CREATE TABLE IF NOT EXISTS "consent_records" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "user_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26),
  "consent_type" VARCHAR(60) NOT NULL,
  "granted" BOOLEAN NOT NULL,
  "granted_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expires_at" TIMESTAMP(3),
  "evidence" JSONB,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_consent_records_school_id" ON "consent_records" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_consent_records_user_id" ON "consent_records" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_consent_records_student_id" ON "consent_records" ("student_id");

CREATE TABLE IF NOT EXISTS "data_requests" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "user_id" CHAR(26) NOT NULL,
  "kind" VARCHAR(40) NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'requested',
  "file_id" CHAR(26),
  "processed_by" CHAR(26),
  "processed_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("kind" IN ('export', 'delete', 'correct')),
  CHECK ("status" IN ('requested', 'processing', 'done', 'rejected'))
);
CREATE INDEX IF NOT EXISTS "ix_data_requests_school_id" ON "data_requests" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_data_requests_user_id" ON "data_requests" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_data_requests_file_id" ON "data_requests" ("file_id");
CREATE INDEX IF NOT EXISTS "ix_data_requests_processed_by" ON "data_requests" ("processed_by");

CREATE TABLE IF NOT EXISTS "retention_policies" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "entity_type" VARCHAR(60) NOT NULL,
  "keep_years" SMALLINT NOT NULL,
  "action" VARCHAR(40) NOT NULL DEFAULT 'archive',
  "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "entity_type"),
  CHECK ("action" IN ('archive', 'anonymise', 'delete'))
);
CREATE INDEX IF NOT EXISTS "ix_retention_policies_school_id" ON "retention_policies" ("school_id");


-- ============ Analytics, BI & predictions ============
CREATE TABLE IF NOT EXISTS "dashboards" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "name" VARCHAR(120) NOT NULL,
  "role_id" CHAR(26),
  "user_id" CHAR(26),
  "layout" JSONB,
  "is_default" BOOLEAN NOT NULL DEFAULT FALSE,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_dashboards_school_id" ON "dashboards" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_dashboards_role_id" ON "dashboards" ("role_id");
CREATE INDEX IF NOT EXISTS "ix_dashboards_user_id" ON "dashboards" ("user_id");

CREATE TABLE IF NOT EXISTS "metrics" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "key_name" VARCHAR(80) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "definition" JSONB,
  "unit" VARCHAR(20),
  "warn_below" NUMERIC(12,2),
  "warn_above" NUMERIC(12,2),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "key_name")
);
CREATE INDEX IF NOT EXISTS "ix_metrics_school_id" ON "metrics" ("school_id");

CREATE TABLE IF NOT EXISTS "metric_values" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "metric_id" CHAR(26) NOT NULL,
  "period" DATE NOT NULL,
  "dimension" VARCHAR(80),
  "value" NUMERIC(14,2) NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("metric_id", "period", "dimension")
);
CREATE INDEX IF NOT EXISTS "ix_metric_values_school_id" ON "metric_values" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_metric_values_metric_id" ON "metric_values" ("metric_id");

CREATE TABLE IF NOT EXISTS "risk_scores" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "student_id" CHAR(26) NOT NULL,
  "risk_type" VARCHAR(40) NOT NULL,
  "score" NUMERIC(5,2) NOT NULL,
  "factors" JSONB,
  "computed_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "acknowledged_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("student_id", "risk_type"),
  CHECK ("risk_type" IN ('dropout', 'fee_default', 'result_decline', 'attendance'))
);
CREATE INDEX IF NOT EXISTS "ix_risk_scores_school_id" ON "risk_scores" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_risk_scores_student_id" ON "risk_scores" ("student_id");
CREATE INDEX IF NOT EXISTS "ix_risk_scores_acknowledged_by" ON "risk_scores" ("acknowledged_by");

CREATE TABLE IF NOT EXISTS "anomaly_alerts" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "metric_key" VARCHAR(80) NOT NULL,
  "detected_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expected" NUMERIC(14,2),
  "actual" NUMERIC(14,2),
  "severity" VARCHAR(40) NOT NULL DEFAULT 'warn',
  "status" VARCHAR(40) NOT NULL DEFAULT 'open',
  "details" JSONB,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("severity" IN ('info', 'warn', 'critical')),
  CHECK ("status" IN ('open', 'acknowledged', 'resolved'))
);
CREATE INDEX IF NOT EXISTS "ix_anomaly_alerts_school_id" ON "anomaly_alerts" ("school_id");

CREATE TABLE IF NOT EXISTS "benchmark_snapshots" (
  "id" CHAR(26) NOT NULL,
  "period" DATE NOT NULL,
  "cohort" VARCHAR(60) NOT NULL,
  "metric_key" VARCHAR(80) NOT NULL,
  "p25" NUMERIC(14,2),
  "p50" NUMERIC(14,2),
  "p75" NUMERIC(14,2),
  PRIMARY KEY ("id"),
  UNIQUE ("period", "cohort", "metric_key")
);


-- ============ AI assistant & automation copilots ============
CREATE TABLE IF NOT EXISTS "ai_conversations" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "user_id" CHAR(26) NOT NULL,
  "channel" VARCHAR(40) NOT NULL DEFAULT 'web',
  "title" VARCHAR(200),
  "context" JSONB,
  "last_message_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("channel" IN ('web', 'app', 'whatsapp', 'sms'))
);
CREATE INDEX IF NOT EXISTS "ix_ai_conversations_school_id" ON "ai_conversations" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_ai_conversations_user_id" ON "ai_conversations" ("user_id");

CREATE TABLE IF NOT EXISTS "ai_messages" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "conversation_id" CHAR(26) NOT NULL,
  "role" VARCHAR(40) NOT NULL,
  "content" TEXT,
  "tool_calls" JSONB,
  "tokens_in" INTEGER NOT NULL DEFAULT 0,
  "tokens_out" INTEGER NOT NULL DEFAULT 0,
  "cost" NUMERIC(10,4) NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("role" IN ('user', 'assistant', 'tool', 'system'))
);
CREATE INDEX IF NOT EXISTS "ix_ai_messages_school_id" ON "ai_messages" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_ai_messages_conversation_id" ON "ai_messages" ("conversation_id");

CREATE TABLE IF NOT EXISTS "ai_generations" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "kind" VARCHAR(40) NOT NULL,
  "requested_by" CHAR(26),
  "input" JSONB,
  "output" JSONB,
  "model" VARCHAR(60),
  "status" VARCHAR(40) NOT NULL DEFAULT 'generated',
  "applied_to_type" VARCHAR(60),
  "applied_to_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("kind" IN ('questions', 'remarks', 'lesson_plan', 'notice', 'summary', 'translation', 'report_narrative', 'other')),
  CHECK ("status" IN ('generated', 'reviewed', 'applied', 'discarded'))
);
CREATE INDEX IF NOT EXISTS "ix_ai_generations_school_id" ON "ai_generations" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_ai_generations_requested_by" ON "ai_generations" ("requested_by");

CREATE TABLE IF NOT EXISTS "ocr_jobs" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "file_id" CHAR(26) NOT NULL,
  "kind" VARCHAR(40) NOT NULL,
  "result" JSONB,
  "confidence" NUMERIC(5,2),
  "status" VARCHAR(40) NOT NULL DEFAULT 'queued',
  "applied_to_type" VARCHAR(60),
  "applied_to_id" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CHECK ("kind" IN ('marks_sheet', 'omr', 'document', 'id_card', 'receipt')),
  CHECK ("status" IN ('queued', 'done', 'needs_review', 'applied', 'failed'))
);
CREATE INDEX IF NOT EXISTS "ix_ocr_jobs_school_id" ON "ocr_jobs" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_ocr_jobs_file_id" ON "ocr_jobs" ("file_id");

CREATE TABLE IF NOT EXISTS "ai_policies" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "features" JSONB,
  "data_scope" JSONB,
  "monthly_budget" NUMERIC(14,2),
  "model" VARCHAR(60),
  "is_enabled" BOOLEAN NOT NULL DEFAULT FALSE,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "ix_ai_policies_school_id" ON "ai_policies" ("school_id");

CREATE TABLE IF NOT EXISTS "ai_usage_monthly" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "month" DATE NOT NULL,
  "tokens_in" BIGINT NOT NULL DEFAULT 0,
  "tokens_out" BIGINT NOT NULL DEFAULT 0,
  "cost" NUMERIC(14,2) NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "month")
);
CREATE INDEX IF NOT EXISTS "ix_ai_usage_monthly_school_id" ON "ai_usage_monthly" ("school_id");


-- ============ Marketplace, plugins & developer platform ============
CREATE TABLE IF NOT EXISTS "plugins" (
  "id" CHAR(26) NOT NULL,
  "slug" VARCHAR(80) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "vendor" VARCHAR(160),
  "description" TEXT,
  "version" VARCHAR(20) NOT NULL,
  "hooks" JSONB,
  "settings_schema" JSONB,
  "price_monthly" NUMERIC(14,2) NOT NULL DEFAULT 0,
  "status" VARCHAR(40) NOT NULL DEFAULT 'draft',
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("slug"),
  CHECK ("status" IN ('draft', 'published', 'suspended'))
);

CREATE TABLE IF NOT EXISTS "plugin_installs" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "plugin_id" CHAR(26) NOT NULL,
  "settings" JSONB,
  "is_enabled" BOOLEAN NOT NULL DEFAULT TRUE,
  "installed_by" CHAR(26),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("school_id", "plugin_id")
);
CREATE INDEX IF NOT EXISTS "ix_plugin_installs_school_id" ON "plugin_installs" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_plugin_installs_plugin_id" ON "plugin_installs" ("plugin_id");
CREATE INDEX IF NOT EXISTS "ix_plugin_installs_installed_by" ON "plugin_installs" ("installed_by");

CREATE TABLE IF NOT EXISTS "oauth_clients" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "client_id" VARCHAR(64) NOT NULL,
  "client_secret_hash" VARCHAR(128) NOT NULL,
  "redirect_uris" JSONB,
  "scopes" JSONB,
  "is_confidential" BOOLEAN NOT NULL DEFAULT TRUE,
  "revoked_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("client_id")
);
CREATE INDEX IF NOT EXISTS "ix_oauth_clients_school_id" ON "oauth_clients" ("school_id");

CREATE TABLE IF NOT EXISTS "oauth_tokens" (
  "id" CHAR(26) NOT NULL,
  "school_id" CHAR(26) NOT NULL,
  "client_id" CHAR(26) NOT NULL,
  "user_id" CHAR(26),
  "token_hash" VARCHAR(128) NOT NULL,
  "kind" VARCHAR(40) NOT NULL,
  "scopes" JSONB,
  "expires_at" TIMESTAMP(3) NOT NULL,
  "revoked_at" TIMESTAMP(3),
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("token_hash"),
  CHECK ("kind" IN ('access', 'refresh', 'authorization_code'))
);
CREATE INDEX IF NOT EXISTS "ix_oauth_tokens_school_id" ON "oauth_tokens" ("school_id");
CREATE INDEX IF NOT EXISTS "ix_oauth_tokens_client_id" ON "oauth_tokens" ("client_id");
CREATE INDEX IF NOT EXISTS "ix_oauth_tokens_user_id" ON "oauth_tokens" ("user_id");

CREATE TABLE IF NOT EXISTS "template_packs" (
  "id" CHAR(26) NOT NULL,
  "slug" VARCHAR(80) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "kind" VARCHAR(40) NOT NULL,
  "locale" VARCHAR(10),
  "content" JSONB,
  "version" VARCHAR(20) NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("slug"),
  CHECK ("kind" IN ('documents', 'notifications', 'accounting', 'grading', 'curriculum', 'forms'))
);


